insert into public.listings (id, owner_id, type, title, title_ar, description, description_ar, category, price_per_day, currency, images, status, visibility, location, created_at, updated_at) values
  ('b9b2de9a-21d3-49b6-a0d4-9a822fa57365', 'd56eff66-903d-452f-a227-8bc643b436d7', 'ITEM', 'Cordless drill — Milwaukee M18', 'دريل لاسلكي — Milwaukee M18', 'Heavy-duty cordless drill with two batteries and a full bit set. Perfect for hanging shelves, curtain rails, or small carpentry. Comes charged and ready to go.', 'دريل لاسلكي قوي ببطاريتين وطقم بنطة كامل. مثالي لتعليق الستائر والأرفف والأعمال الخشبية الصغيرة. يوصلك مشحون وجاهز للشغل.', 'tools', '25.00', 'EGP', array['/img/tools-drill.jpg', '/img/tools-pegboard.jpg'], 'ACTIVE', 'PUBLIC', 'El-Bahri', '2026-09-23T10:24:24.112Z'::timestamptz, '2026-09-23T10:24:24.112Z'::timestamptz),
  ('a08e0f3f-d97f-44a0-84c5-16a620c4cb96', 'd56eff66-903d-452f-a227-8bc643b436d7', 'ITEM', 'Complete home toolbox', 'شنطة عدة كاملة للبيت', 'Everything a home needs: hammer, screwdrivers, wrenches, tape measure, level and a hacksaw. Borrow it for a day instead of buying tools you will use once.', 'كل اللي البيت محتاجه: شاكوش ومفكات ومفاتيح إنجليز ومتر مياه واسبيريت ومنشار. استعيره يوم بدل ما تشتري عدة هتستخدمها مرة واحدة.', 'tools', '15.00', 'EGP', array['/img/tools-toolbox.jpg'], 'ACTIVE', 'PUBLIC', 'El-Gaish St.', '2026-09-23T10:24:24.260Z'::timestamptz, '2026-09-23T10:24:24.260Z'::timestamptz),
  ('d65c78fe-49f8-491c-b155-09a37b127fc6', 'd56eff66-903d-452f-a227-8bc643b436d7', 'ITEM', 'Aluminum ladder — 3 meters', 'سلم ألوميتال ٣ أمتار', 'Light, sturdy 3-meter aluminum ladder. Folds flat and fits in any car trunk. Great for painting, AC filters, and high shelves.', 'سلم ألوميتال خفيف ومتين بطول ٣ أمتار، يتطوى ويدخل شنطة أي عربية. ممتاز للدهان وتنظيف الفلاتير والأرفف العالية.', 'tools', '20.00', 'EGP', array['/img/tools-ladder.jpg'], 'ACTIVE', 'PUBLIC', 'Shanawan', '2026-09-23T10:24:24.407Z'::timestamptz, '2026-09-23T10:24:24.407Z'::timestamptz),
  ('e31bafb8-927b-483f-9f5d-a8f29c3014b1', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 'ITEM', 'Electric sewing machine', 'ماكينة خياطة كهربائية', 'Reliable home sewing machine for hems, repairs and light tailoring. I include spare needles and thread, and I am happy to show you the basics.', 'ماكينة خياطة منزلية شغالة كويس للتقصير والإصلاحات والخياطة الخفيفة. معاها إبر وخيط احتياطي، وممكن أعلمك الأساسيات في دقايق.', 'crafts', '30.00', 'EGP', array['/img/sewing.jpg'], 'ACTIVE', 'PUBLIC', 'El-Khadra', '2026-09-23T10:24:24.556Z'::timestamptz, '2026-09-23T10:24:24.556Z'::timestamptz),
  ('b4c97665-2a01-4cf5-8191-a1c15bd046a9', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 'ITEM', 'Stand mixer — 7 liters', 'عجان كهربائي ٧ لتر', 'Baking a cake or kneading for a big family lunch? This 7L stand mixer handles it all. Cleaned and sanitized before every loan.', 'بتعملي كيك أو بتعجني لعزيمة كبيرة؟ العجان ده سعة ٧ لتر يشيل الشغل كله. بيتنضف وبيتعقم قبل كل إعارة.', 'kitchen', '40.00', 'EGP', array['/img/kitchen-mixer.jpg'], 'ACTIVE', 'PUBLIC', 'City Center', '2026-09-23T10:24:24.705Z'::timestamptz, '2026-09-23T10:24:24.705Z'::timestamptz),
  ('88d4efa3-fff6-4e8d-960c-a9af5726864f', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 'SKILL', 'Home cooking for gatherings', 'طبخ عزومات وولائم في البيت', 'I cook Egyptian home dishes for family gatherings: mahshi, molokhia, roasted meats and desserts. You provide the ingredients, I bring the experience.', 'بطبخ أكل بيتي مصري للعزايم: محشي وملوخية ولحوم محمرة وحلويات. أنت تجيب المقادير وأنا أجيب الخبرة والإيد الشاطرة.', 'kitchen', '200.00', 'EGP', array['/img/kitchen-cook.jpg'], 'ACTIVE', 'PUBLIC', 'City Center', '2026-09-23T10:24:24.855Z'::timestamptz, '2026-09-23T10:24:24.855Z'::timestamptz),
  ('78bfbcb6-1a1b-4710-875c-3db093917395', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 'SKILL', 'Arabic calligraphy & drawing', 'خط عربي ورسم', 'Patient, friendly lessons in Arabic calligraphy (Ruqaa and Naskh) and basic drawing for kids and adults. Materials included in the first session.', 'حصص هادية وودية في الخط العربي (رقعة ونسخ) وأساسيات الرسم للكبار والصغار. الخامات متوفرة في أول حصة مجانًا.', 'crafts', '45.00', 'EGP', array['/img/art-supplies.jpg'], 'ACTIVE', 'PUBLIC', 'El-Khadra', '2026-09-23T10:24:25.002Z'::timestamptz, '2026-09-23T10:24:25.002Z'::timestamptz),
  ('b5a6e463-1762-4308-ba04-0943b5ef1531', 'be472343-b0cd-466a-9fd5-75f2f1308a84', 'ITEM', 'Canon DSLR camera', 'كاميرا كانون DSLR', 'Canon DSLR with an 18–55mm lens, tripod and spare battery. Great for graduations, birthdays, or trying photography before buying.', 'كاميرا كانون DSLR بعدسة ١٨–٥٥ وحامل ثلاثي وبطارية احتياطية. مناسبة للتخرج وأعياد الميلاد، أو تجرب التصوير قبل ما تشتري.', 'electronics', '120.00', 'EGP', array['/img/camera.jpg'], 'ACTIVE', 'PUBLIC', 'East Branch', '2026-09-23T10:24:25.150Z'::timestamptz, '2026-09-23T10:24:25.150Z'::timestamptz),
  ('a53a725d-f763-428e-8caa-d83f55aac508', 'be472343-b0cd-466a-9fd5-75f2f1308a84', 'ITEM', 'Movie-night projector', 'بروجيكتور ليلة سينما', 'Full-HD projector with a 2.5m screen and HDMI cables. Turn your roof or living room into a cinema. Popcorn not included — yet.', 'بروجيكتور Full HD بشاشة ٢.٥ متر وكابلات HDMI. حوّل سطح البيت أو الصالة إلى سينما. الفشار مش شامل العرض... لسه.', 'electronics', '60.00', 'EGP', array['/img/projector.jpg'], 'ACTIVE', 'PUBLIC', 'East Branch', '2026-09-23T10:24:25.300Z'::timestamptz, '2026-09-23T10:24:25.300Z'::timestamptz),
  ('5aecc787-5670-4142-9406-c3725bfd5318', 'be472343-b0cd-466a-9fd5-75f2f1308a84', 'SKILL', 'Math tutoring — Thanaweya Amma', 'حصص رياضيات للثانوية العامة', 'Certified math teacher offering one-on-one Thanaweya Amma sessions at your home or mine. Clear explanations, past-paper practice, weekly follow-up.', 'مدرّسة رياضيات بتدي جلسات فردية للثانوية العامة في بيتك أو بيتي. شرح واضح وحل امتحانات ومتابعة أسبوعية بأوراق عمل.', 'lessons', '60.00', 'EGP', array['/img/study-books.jpg'], 'ACTIVE', 'PUBLIC', 'City Center', '2026-09-23T10:24:25.449Z'::timestamptz, '2026-09-23T10:24:25.449Z'::timestamptz),
  ('8b1e3a6b-f595-4d4e-a0b3-18b850ef7c07', '958ebd55-435a-49c3-996e-aa8578fccc05', 'ITEM', 'Hybrid city bike', 'عجلة هجين للمدينة', 'Comfortable hybrid bike, freshly tuned, with a lock and a pump. Perfect for getting around Shibin or a weekend ride along the canal.', 'عجلة مريحة مضبوطة حديثًا ومعها كابل وطلمبة. ممتازة للمشاوير في شبين أو فسحة آخر الأسبوع على الكورنيش.', 'sports', '25.00', 'EGP', array['/img/bike.jpg'], 'ACTIVE', 'PUBLIC', 'El-Bahri', '2026-09-23T10:24:25.598Z'::timestamptz, '2026-09-23T10:24:25.598Z'::timestamptz),
  ('e1da073e-982c-4178-bfd0-fa020b11c39d', '958ebd55-435a-49c3-996e-aa8578fccc05', 'ITEM', 'Camping tent — 4 people', 'خيمة تخييم ٤ أفراد', 'Waterproof 4-person tent with mats and a lantern. Take it for a beach trip or a desert camp; it packs into one bag.', 'خيمة ٤ أفراد ضد الماء ومعها مراتب وفانوس. خدها رحلة الساحل أو تخييم الصحراء؛ بتتلم في شنطة واحدة.', 'sports', '80.00', 'EGP', array['/img/tent.jpg'], 'ACTIVE', 'PUBLIC', 'Shanawan', '2026-09-23T10:24:25.747Z'::timestamptz, '2026-09-23T10:24:25.747Z'::timestamptz),
  ('b6ca8fca-9504-489f-9510-8b27f768dd84', '958ebd55-435a-49c3-996e-aa8578fccc05', 'SKILL', 'Guitar for beginners', 'تعليم جيتار للمبتدئين', 'Learn your first ten songs on acoustic guitar. I teach kids and adults at your pace, and you can practice on my guitar between lessons.', 'اتعلم أول عشر أغاني على الجيتار. بعلّم كبار وصغار بالراحة وعلى مزاجك، وتقدر تتمرن على جيتاري بين الحصص.', 'lessons', '70.00', 'EGP', array['/img/guitar.jpg'], 'ACTIVE', 'PUBLIC', 'El-Bahri', '2026-09-23T10:24:25.897Z'::timestamptz, '2026-09-23T10:24:25.897Z'::timestamptz),
  ('d5229777-bb08-4320-84e6-973f5a2b142f', 'c0865baa-a8f8-4f12-9c40-524e6a3cbfb2', 'SKILL', 'Plumbing & faucet repairs', 'تصليح سباكة وخلاطات', 'Licensed plumber for leaks, faucet swaps, water heaters and drainage. Fair prices for neighbors and I show up the same day.', 'سباك مرخص لكشف التسريبات وتغيير الخلاطات والسخانات وتسليك المواسير. أسعار جيران ونزول في نفس اليوم.', 'repairs', '75.00', 'EGP', array['/img/handyman.jpg'], 'ACTIVE', 'PUBLIC', 'El-Gaish St.', '2026-09-23T10:24:26.045Z'::timestamptz, '2026-09-23T10:24:26.045Z'::timestamptz),
  ('b67061a5-6bd0-4dd0-b99a-56b886e56d6f', 'c0865baa-a8f8-4f12-9c40-524e6a3cbfb2', 'SKILL', 'Coding for kids & beginners', 'برمجة للأطفال والمبتدئين', 'Software engineer teaching kids and beginners: logic, Scratch, then Python. Small groups at my place or online, twice a week.', 'مهندس برمجيات بعلّم الأطفال والمبتدئين: منطق ثم Scratch ثم بايثون. مجموعات صغيرة عندي أو أونلاين مرتين في الأسبوع.', 'lessons', '90.00', 'EGP', array['/img/laptop-code.jpg'], 'ACTIVE', 'PUBLIC', 'Shanawan', '2026-09-23T10:24:26.196Z'::timestamptz, '2026-09-23T10:24:26.196Z'::timestamptz),
  ('229170ac-1e1d-4914-a30c-fd6281780189', '958ebd55-435a-49c3-996e-aa8578fccc05', 'SKILL', 'Balcony garden setup', 'تنسيق حديقة البلكونة', 'I help you turn a plain balcony into a green corner: pots, soil, easy plants, and a watering plan that fits your schedule.', 'بأساعدك تحوّل البلكونة إلى ركن أخضر: أصص وتربة ونباتات سهلة وخطة ري تناسب وقتك.', 'garden', '50.00', 'EGP', array['/img/garden-green.jpg'], 'ACTIVE', 'PUBLIC', 'East Branch', '2026-09-23T10:24:26.345Z'::timestamptz, '2026-09-23T10:24:26.345Z'::timestamptz),
  ('8721c116-2540-4772-bc22-64c3d0cd21c2', '4f45fec0-83fc-4d67-bc25-0a2cd4275427', 'SKILL', 'Car & balcony pressure wash', 'غسيل عربيات وبلكونات بالضغط', 'Deep clean for cars, balconies and entrances using a pressure washer and eco soap. One visit leaves everything looking new.', 'تنظيف عميق للعربيات والبلكونات والمداخل بماكينة ضغط وصابون صديق للبيئة. زيارة واحدة وترجع كلها زي الجديدة.', 'cleaning', '100.00', 'EGP', array['/img/cleaning.jpg'], 'ACTIVE', 'PUBLIC', 'El-Bahri', '2026-09-23T10:24:26.495Z'::timestamptz, '2026-09-23T10:24:26.495Z'::timestamptz)
insert into public.reviews (id, listing_id, author_id, rating, comment, created_at) values
  ('471181bd-cc26-44c1-b7ce-41ab0326c96c', 'b9b2de9a-21d3-49b6-a0d4-9a822fa57365', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 5, 'Amazing neighbor — the drill came charged with every bit I needed. — جاااار محترم، الدريل وصل مشحون ومعه كل البنط اللي احتجتها.', '2026-09-23T10:24:26.645Z'::timestamptz),
  ('95716332-3a4d-4ee6-856a-f6d4b3d37a9c', 'b9b2de9a-21d3-49b6-a0d4-9a822fa57365', 'c0865baa-a8f8-4f12-9c40-524e6a3cbfb2', 5, 'Quick handover, great condition. Saved me 900 EGP easily. — استلام وتسليم سريع والعدة حالة ممتازة. وفّر عليا فلوس شراء دريل جديد.', '2026-09-23T10:24:26.793Z'::timestamptz),
  ('62530d86-e40a-4652-a619-9d957ce3c7e5', 'b9b2de9a-21d3-49b6-a0d4-9a822fa57365', '958ebd55-435a-49c3-996e-aa8578fccc05', 4, 'Very helpful and flexible with timing. — متعاون جدًا ومرونة في المعاد.', '2026-09-23T10:24:26.943Z'::timestamptz),
  ('de4e47fc-077c-4296-aabf-19999b7bb152', 'b4c97665-2a01-4cf5-8191-a1c15bd046a9', 'be472343-b0cd-466a-9fd5-75f2f1308a84', 5, 'The mixer is spotless and Mona even sent the cake recipe! — العجان نضيف جدًا ومنى بعتت معاه وصفة الكيك كمان!', '2026-09-23T10:24:27.091Z'::timestamptz),
  ('4a7f8320-b9a4-4f85-b287-084cb2390b8c', 'b5a6e463-1762-4308-ba04-0943b5ef1531', '958ebd55-435a-49c3-996e-aa8578fccc05', 5, 'Sara explained every button. My daughter graduation photos came out perfect. — سارة شرحتلي كل زرار. صور تخرج بنتي طلعت تحفة.', '2026-09-23T10:24:27.238Z'::timestamptz),
  ('33ac48ad-ed4b-4840-82ba-320ba8605ddd', 'e31bafb8-927b-483f-9f5d-a8f29c3014b1', 'be472343-b0cd-466a-9fd5-75f2f1308a84', 4, 'Good machine and a kind owner who taught me the basics. — ماكينة كويسة وصاحبتها علمتني الأساسيات بصدر رحب.', '2026-09-23T10:24:27.385Z'::timestamptz),
  ('18ad5e96-e19f-493c-a55e-a4af2762797a', 'd5229777-bb08-4320-84e6-973f5a2b142f', '4f45fec0-83fc-4d67-bc25-0a2cd4275427', 5, 'Khaled fixed two leaks in twenty minutes. Fair price, clean work. — خالد صلّح تسريبين في عشرين دقيقة. سعر عادل وشغل نضيف.', '2026-09-23T10:24:27.533Z'::timestamptz),
  ('360dff7c-04ac-4e1b-bb4d-67d33dff71e3', '8b1e3a6b-f595-4d4e-a0b3-18b850ef7c07', 'c0865baa-a8f8-4f12-9c40-524e6a3cbfb2', 4, 'Smooth ride and a solid lock included. — عجلة تقيلة ومعاها كابل متين.', '2026-09-23T10:24:27.680Z'::timestamptz),
  ('0585918b-33bf-4b1b-bd16-c1af51abfc82', 'e1da073e-982c-4178-bfd0-fa020b11c39d', 'd56eff66-903d-452f-a227-8bc643b436d7', 5, 'Took it to Ras El-Bar, zero leaks in the rain. — خدتها رأس البر ومقطرتش نقطة مطر جواها.', '2026-09-23T10:24:27.827Z'::timestamptz),
  ('80da946c-0123-403c-8d9a-445e297081c5', '5aecc787-5670-4142-9406-c3725bfd5318', 'b0963f45-a0f8-4f6b-a52d-6beb4c17a2be', 5, 'My son went from 60% to 92% in one term. Highly recommended. — ابني طلع من ٦٠٪ لـ ٩٢٪ في ترم واحد. أنصح بيها جدًا.', '2026-09-23T10:24:27.975Z'::timestamptz),
  ('abfa1a69-f8ab-4205-96bf-f3a9eaac59fc', 'a08e0f3f-d97f-44a0-84c5-16a620c4cb96', '958ebd55-435a-49c3-996e-aa8578fccc05', 5, 'Why buy tools? Ahmed is the definition of a good neighbor. — ليش أشترى عدة وأحمد موجود؟ تعريف الجار الجدع.', '2026-09-23T10:24:28.123Z'::timestamptz)
insert into public.bookings (id, listing_id, requester_id, start_date, end_date, status, message, created_at, updated_at) values
